 public static int CategoryOf(string key){
  if(key.StartsWith("action:"))key=key.Substring(7);
  if(key=="ui:autodrive" || key=="get autodrive" || key=="ultra_autodrive" || key=="vehicle_god" || key=="vehicle_tuning" || key=="ui:vehicle" || key=="act vehicle_upright" || key=="get vehicle")return 11;
  if(key=="act appearance")return 10;
  if(key=="ui:cyber_slots" || key=="act os_next")return 4;
  if(new[]{"dialogue_timer","dialogue_lifepath","dialogue_skills"}.Contains(key))return 9;
  if(new[]{"god","stamina","oxygen","fall","heal_cd","get vitals"}.Contains(key))return 1;
  if(new[]{"no_reload","accuracy","no_recoil","one_hit","grenade_cd","launcher_cd","melee_combo","ui:edit:fire_rate"}.Contains(key))return 2;
  if(new[]{"stealth","ghost","ghost_crouch","police_ignore","act wanted"}.Contains(key))return 3;
  if(new[]{"cyber_capacity","no_cyberpsychosis","ram","instant_scan","quickhack_fast","netrunner_stealth","device_off","device_friendly","sandevistan","sandy_freeze","blackwall","skills_cd","quickhack_cd","act sandy","act blackwall","act remove_extras","auto_breach","breach_timer","act breach","ui:edit:blackwall_targets","ui:edit:blackwall_range"}.Contains(key))return 4;
  if(new[]{"noclip","multijump","infinite_air","dash_free","blink","act blink","act waypoint","act quest","get travel","act travel_cancel","ui:edit:blink_distance","ui:edit:flight_speed","ui:edit:dash_strength","ui:edit:speed","ui:edit:jump"}.Contains(key))return 5;
  if(key=="unlimited_xp" || key=="unlimited_cred" || key.StartsWith("ui:edit:") && !new[]{"ui:edit:game_speed","ui:edit:carry"}.Contains(key) || key=="act max_skills" || key=="act max_all")return 6;
  if(new[]{"items_ammo","items_no_decrease","free_craft","free_upgrade","act recipes","components","qh_components","massive_carry","ui:items","ui:edit:carry"}.Contains(key))return 7;
  return 8;
 }
